ALTER TABLE games MODIFY executable VARCHAR(255) NULL;
ALTER TABLE games ADD COLUMN cover_url VARCHAR(1000) NULL AFTER description;
ALTER TABLE games ADD COLUMN banner_url VARCHAR(1000) NULL AFTER cover_url;
ALTER TABLE games ADD COLUMN local_cover_path VARCHAR(500) NULL AFTER banner_url;
ALTER TABLE games ADD COLUMN local_banner_path VARCHAR(500) NULL AFTER local_cover_path;

CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  user_id BIGINT UNSIGNED NOT NULL,
  token_hash CHAR(64) NOT NULL UNIQUE,
  expires_at DATETIME NOT NULL,
  used_at DATETIME NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_reset_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  INDEX idx_reset_expiry (expires_at, used_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

DELETE FROM games WHERE slug IN ('neon-horizon','echoes-of-anatolia','lime-protocol');

ON DUPLICATE KEY UPDATE name=VALUES(name),is_active=1;

